{
  "item_id": "PRISMA_2020_3",
  "elements": [
    {
      "element_id": "prisma_2020_3_e1",
      "status": "PARTIAL",
      "chunk_id": "text_6",
      "quote": "Currently, there are only a few interventions hat seem able to benefit the clinical course of COVID-19 [3]. Therefore, preventive measures are of vital importance to control COVID-19. The scientific, medical, and industrial communities have embarked on efforts to develop safe vaccines [4, 5]. At September 13 th , 2021 about 104 vaccines are being tested in humans, with 33 having reached phase III trials [6].",
      "reason": "Provides the current knowledge context (limited interventions and active vaccine development) but does not clearly describe specific remaining uncertainties in the evidence beyond the need for critical appraisal."
    },
    {
      "element_id": "prisma_2020_3_e2",
      "status": "PRESENT",
      "chunk_id": "text_6",
      "quote": "With the rapid development, approval of vaccines for COVID-19, and the growing number of viral variants, there is a need for systematic reviews critically appraising the topic.",
      "reason": "Explicitly explains the importance/need for conducting the review in light of rapidly evolving approvals and viral variants."
    },
    {
      "element_id": "prisma_2020_3_e3",
      "status": "PRESENT",
      "chunk_id": "text_6",
      "quote": "We recently published the first version of our review as a preprint, showing effects of mRNA and viral vector vaccines [7]. The aim of this second version of our living systematic review is to assess the effectiveness and safety of COVID-19 vaccines through analyses of all currently available randomized clinical trials.",
      "reason": "Identifies an existing (previous) version of the review and explains why a current (second/living) version is needed (expanding to all available randomized clinical trials and assessing effectiveness and safety)."
    },
    {
      "element_id": "prisma_2020_3_e4",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No information is provided describing a proposed mechanism of action of the interventions (vaccines) in the retrieved evidence."
    },
    {
      "element_id": "prisma_2020_3_e5",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "The retrieved evidence does not provide a logic model or hypothesised relationships between intervention components and outcomes."
    }
  ],
  "confidence": 67
}

